// Helper variables
__var savedAP    = __ap;
__var value      = 0x00000000;

Message(0, "Begin CS_TIMESTAMP_GENERATOR___INSTANCE_INDEX___Configure @0x%08X, AP 0x%08X", TIMESTAMP_GENERATOR___INSTANCE_INDEX___ADDRESS, TIMESTAMP_GENERATOR___INSTANCE_INDEX___AP);

__ap = TIMESTAMP_GENERATOR___INSTANCE_INDEX___AP; // Set AP

// TODO: Find out if the control interface is accessible to debugger!!
//       Documentation not entirely clear to me.

__ap = savedAP;
Message(0, "End CS_TIMESTAMP_GENERATOR___INSTANCE_INDEX___Configure @0x%08X, AP 0x%08X", TIMESTAMP_GENERATOR___INSTANCE_INDEX___ADDRESS, TIMESTAMP_GENERATOR___INSTANCE_INDEX___AP);
